// === Tab: main.js ===
/*
Falling Lines

Particles fall and are slowed down by air drag that is being driven from a noise field.

jasonlabbe3d.com
twitter.com/russetPotato
*/

var spawnCount = 6;
var noiseScale = 0.01;
var noiseSpeed = 1;
var allParticles = [];
var globalHue = 0;
let lapse = 0;    // mouse timer

function setup() {
	createCanvas(1112, 834);
	background(0);	
	rectMode(CENTER);
	colorMode(HSB, 255);
	noStroke();
}

function draw() {
	background(160, 120, 255, 200);

	for (let i = 0; i < spawnCount; i++) {
		allParticles.push(new Particle(random(width), -100));
	}

	for (let i = allParticles.length - 1; i > -1; i--) {
		let p = allParticles[i];

		p.acc.add(new p5.Vector(0, p.fallRate));

		let n = noise(
			(frameCount * (noiseSpeed * 2) + p.pos.x) * noiseScale, 
			(frameCount * noiseSpeed + p.pos.y) * noiseScale);

		if (n > 0.5) {
			p.vel.mult(p.resistance);
		}

		p.vel.add(p.acc);8
		p.pos.add(p.vel);
		p.acc.mult(0);
		p.angle += p.vel.mag();

		fill(p.hue, 255, 225, max(0, 255 - p.vel.mag() * 30));
		push();
		translate(p.pos.x, p.pos.y);
		rotate(radians(p.angle));
		rect(0, 0, p.width, max(0, p.height - p.vel.mag() * 10));
		pop();

		if (p.pos.y > height) {
			allParticles.splice(i, 1);
		}
	}
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
} 

// === Tab: particle.js ===
function Particle(x, y) {
  this.pos = new p5.Vector(x, y);
  this.vel = new p5.Vector(0, 0);
  this.acc = new p5.Vector(0, 0);

	this.angle = 0;
	this.fallRate = random(0.1, 0.2);
	this.resistance = random(0.85, 0.98);

	this.width = random(1.5, 4);
	this.height = random(50, 100);

	this.hue = globalHue;
	globalHue = (globalHue + 0.05) % 255;
}

